# -*- coding: utf-8 -*-
"""English translations, batch 14 (40 figures)."""
EN = {
"以利押": dict(lesson="Imposing in appearance, but God looks at the heart",
 summary="David's eldest brother.",
 witness="Eliab was Jesse's firstborn and David's eldest brother, tall in stature. On seeing him Samuel thought 'surely the LORD's anointed is before Him,' but God said: do not look on his appearance... man looks on the outward, but the LORD looks on the heart. He later despised David who came bringing bread. An imposing appearance does not equal a heart after God.",
 follow=[],
 caution=["Relying on appearance and seniority","Despising the younger one, after God's heart"],
 applications=["Don't measure people or yourself by looks, stature, or seniority","Value whether the heart is after God's heart","Don't despise the 'nobodies' God has chosen"],
 prayer="Lord, Eliab was imposing, yet You chose David's heart. Make me not rely on appearance or despise people, but seek a heart after Your heart. Amen."),
"亚比拿达（大卫之兄）": dict(lesson="A passed-over brother, each has his place",
 summary="Jesse's second son, David's brother.",
 witness="Abinadab was Jesse's second son and David's brother. When Samuel anointed a king he too passed before Samuel, yet God did not choose him. He later served in Saul's army. God's choice is not by birth order or appearance; the passed-over also have their own duty to keep.",
 follow=["Accepting that God's choice is not by human preference, content in his duty"],
 caution=["Not becoming jealous and resentful because passed over"],
 applications=["When another is chosen and you are passed over, still calmly do your duty","Don't judge God's choice by birth order or seniority","Be faithful in your own place, without envy"],
 prayer="Lord, Abinadab was passed over, yet David was chosen. Make me, when passed over, still content in my duty, without jealousy, firmly trusting Your choice has its own good purpose. Amen."),
"沙玛（大卫之兄）": dict(lesson="High in birth order, yet not God's chosen",
 summary="Jesse's third son, David's brother.",
 witness="Shammah was Jesse's third son and David's brother. When Samuel anointed a king he too passed before Samuel, yet God did not choose him. He later served in Saul's army. All three brothers were passed over, and God chose the youngest, the shepherd—God's choice never follows the order people value.",
 follow=["Accepting God's choice not by human preference, content in his duty"],
 caution=["Not despising the chosen one because passed over"],
 applications=["When God chooses another, still be content in your place","Don't rely on birth order or seniority","Don't envy when passed over; be faithful in your duty"],
 prayer="Lord, Shammah was passed over, David was chosen. Make me, when passed over, content in my duty, not envying the chosen, firmly trusting Your choice has its own good purpose. Amen."),
"他玛（大卫之女）": dict(lesson="A violated noble princess—God will surely watch over",
 summary="David's daughter, Absalom's sister, violated by Amnon.",
 witness="Tamar was David's daughter and Absalom's sister, beautiful and noble, yet violated by her half-brother Amnon's scheme, and lived desolate thereafter. Innocently harmed, she became the start of the tragedy of David's house. Her experience reminds us: even in a noble house, sin can cause deep harm; but the harmed, God watches over.",
 follow=["Keeping her dignity as a person amid being harmed"],
 caution=["(A warning to victims) guard against harm among acquaintances, value protection"],
 applications=["Offer protection and support to the violated, not blame","Value boundaries and protection within the family","Trust God watches over and will avenge the harmed"],
 prayer="Lord, Tamar was innocently harmed and lived desolate. Comfort all who are violated, be their watcher and avenger, and make me one who protects rather than harms people. Amen."),
"基利押": dict(lesson="A name appears once, then falls silent",
 summary="A son of David and Abigail.",
 witness="Chileab was a son of David and Abigail, the second born. Scripture mentions him only once in the list of David's sons, with no further record—he may have died young. In the illustrious royal house, he is one nearly forgotten—yet the forgotten by people are not forgotten by God.",
 follow=[],
 caution=[],
 applications=["Even if forgotten by the world, trust God remembers you","Don't make 'being remembered' the goal of life, but pleasing God","Treasure every life, though its deeds be few"],
 prayer="Lord, Chileab was nearly forgotten by people, yet You remembered him. Make me live not to be remembered by people but to be remembered by You, and teach me to treasure every seemingly ordinary life. Amen."),
"巴西莱": dict(lesson="An elder who supplied generously in distress",
 summary="A Gileadite who supplied David when fleeing.",
 witness="Barzillai was an old man of Gilead, exceedingly wealthy. When David was fleeing Absalom at his most wretched, he brought beds, grain, and food to support the king and his followers. Later David invited him to the palace to enjoy life, but he humbly declined, asking only to return home to spend his last years in peace. An elder generous in distress and detached before glory.",
 follow=["Supplying generously when others are in distress and wretched","Detached and content before honor and reward, not coveting"],
 caution=[],
 applications=["Reach out a supplying hand at another's hardest time","Hold a detached, content heart before fame and reward","Be an example of an elder who is generous and not greedy"],
 prayer="Lord, Barzillai supplied generously in David's distress, yet was detached and content before glory. Make me generous in others' distress and content before fame, generous and not greedy. Amen."),
"洗巴": dict(lesson="Taking advantage of his master's misfortune for private gain",
 summary="A servant of Saul's house, serving Mephibosheth.",
 witness="Ziba was a servant of Saul's house, assigned to serve Mephibosheth. When David fled Absalom, he came with provisions, but took the chance to slander, saying his master Mephibosheth hoped to restore the kingdom, and cheated him of his estate. Slandering for private gain in his master's misfortune is a servant's unfaithfulness.",
 follow=["Timely bringing supplies in his master's distress (an outward good)"],
 caution=["Slandering and seeking private gain in his master's misfortune","Framing people and seizing an estate with false words"],
 applications=["Don't seek private gain or speak ill of people in their misfortune","Hold true loyalty when those you serve are in trouble","Don't scoop up benefits for yourself with slander"],
 prayer="Lord, Ziba slandered for private gain in his master's misfortune. Remove from me the heart that profits from chances and harms with slander, making me hold true loyalty toward those I serve. Amen."),
"示每": dict(lesson="Cursing while another is in misfortune",
 summary="A Benjamite who cursed David when he fled.",
 witness="Shimei was a Benjamite, a man of Saul's house. When David was fleeing Absalom at his most wretched, he cursed along the way and threw stones, calling David 'a man of blood, a worthless man.' But David would not let anyone kill him, leaving vengeance to God. Later when David returned, he hurried to beg for mercy. Kicking a man when he's down is base.",
 follow=[],
 caution=["Kicking a man when down and cursing in his misfortune","Bending with the wind, begging mercy when the other gains power"],
 applications=["Don't kick a man when he's down","Guard your mouth, not seizing the chance to curse and shame people","Imitate David: when insulted, leave vengeance to God"],
 prayer="Lord, Shimei cursed David in his misfortune. Remove from me the heart that kicks people when down and speaks evil, making me merciful in others' distress; and when insulted, let me leave vengeance to You like David. Amen."),
"亚比筛": dict(lesson="Loyal and brave, yet his fierceness needs restraint",
 summary="Son of Zeruiah, Joab's brother, one of David's mighty men.",
 witness="Abishai was the son of Zeruiah, Joab's brother, one of David's mighty men, who once alone saved David from a Philistine giant. He was exceedingly loyal and brave to David, yet also very fierce, twice wanting to kill Shimei who cursed David, and to kill the sleeping Saul, both stopped by David. Loyalty and bravery unrestrained easily crosses the line.",
 follow=["Exceedingly loyal to the one he served, risking his life to protect","Brave and decisive, stepping forward in danger"],
 caution=["Fierceness over the top, ready to take life at the slightest","Needing to be restrained by higher mercy and wisdom"],
 applications=["Serve with loyalty and bravery, but let fierceness be restrained","Step forward in danger, but not cross the line of mercy","Learn to hold back when one should forgive and entrust"],
 prayer="Lord, Abishai was loyal and brave yet hard to restrain his fierceness. Give me loyalty and bravery, and restrain my fierceness with Your mercy, that I not cross the proper line. Amen."),
"亚撒黑": dict(lesson="Brave but rash, fast running cost his life",
 summary="Son of Zeruiah, fast of foot, killed by Abner.",
 witness="Asahel was the son of Zeruiah, Joab's brother, one of David's mighty men, swift as a wild gazelle. On the battlefield he relentlessly pursued Abner; Abner urged him again and again to turn aside, but he would not listen, and was finally killed by Abner's backstroke. Rare bravery and speed, cut short by rashness in not heeding counsel.",
 follow=["Having outstanding bravery and agility"],
 caution=["Showing off bravery on talent, rash and not heeding counsel","Not willing to stop when one should stop"],
 applications=["When exercising a gift, also take counsel","Brave but not rash, knowing when to stop","Don't show off strength on talent, harming yourself"],
 prayer="Lord, Asahel was brave but rash and lost his life. Make me use the talents You give well, with the wisdom to take counsel, brave but not rash, knowing when to stop. Amen."),
"雅朔班": dict(lesson="Chief of the mighty men, killing many at one stroke",
 summary="Chief of David's mighty men, also called Josheb-basshebeth.",
 witness="Jashobeam (also Josheb-basshebeth) was the chief of David's mighty men. He once killed three hundred (or eight hundred) at one time, bravest of the brave. He put his outstanding strength wholly to protecting the king God anointed—the greater the gift, the more it should be used in the right place.",
 follow=["Putting outstanding gifts to protecting and advancing God's work","Being a leader and standard-setter among the mighty men"],
 caution=["Not boasting in bravery, giving God the glory"],
 applications=["Put your strongest gift to God's ministry","Be a standard-setter and leader in the team","Give God the glory in victory, not boasting"],
 prayer="Lord, Jashobeam, bravest of the brave, faithfully guarded the anointed king. Make me put my strongest gift to Your work, a leader who sets the standard, giving You glory in victory. Amen."),
"以利亚撒（大卫勇士）": dict(lesson="Holding fast to the end, his hand cleaved to the sword",
 summary="One of David's three mighty men.",
 witness="Eleazar was one of David's three mighty men. Once in battle against the Philistines, the men retreated, but he alone stood and struck down the enemy until his hand was weary, 'his hand cleaving to the sword,' and that day the LORD worked a great deliverance through him. When all others retreated, he held on—victory often belongs to the one who will not let go.",
 follow=["Still holding his post when all retreated","Persisting to the end, until God worked deliverance"],
 caution=["Not retreating with the crowd in hardship"],
 applications=["When everyone gives up, still hold what you should hold","Persist to the end in spiritual battle, not letting go","Trust God will work deliverance through the one who holds on"],
 prayer="Lord, Eleazar held on till his hand cleaved to the sword, and You worked a great deliverance through him. Give me the strength to hold to the end, standing firm when all retreat, until I see Your deliverance. Amen."),
"沙玛（大卫勇士）": dict(lesson="The courage to defend one bean field alone",
 summary="One of David's three mighty men, who alone defended a bean field and defeated the Philistines.",
 witness="Shammah was one of David's three mighty men. Once the Philistines came in a band, the people fled, but he alone stood his ground in a field of lentils, struck down the Philistines, and the LORD gave Israel a great victory. To hold a seemingly insignificant 'bean field,' he stood alone—faithfulness does not pick the size of the post.",
 follow=["Standing alone for the place entrusted, not fleeing with the crowd","Valuing a seemingly insignificant yet duty-bound post"],
 caution=[],
 applications=["Hold your 'bean field' (duty), even when others all retreat","Don't easily give up because the post is insignificant","Trust God works deliverance through the faithful who hold on"],
 prayer="Lord, Shammah stood alone for one bean field, and You gave Israel victory. Give me the courage to hold my duty, standing firm even when the post is small and all retreat. Amen."),
"洗鲁雅": dict(lesson="A mother who raised three fierce warriors",
 summary="David's sister, mother of Joab, Abishai, and Asahel.",
 witness="Zeruiah was David's sister, mother of the three mighty men Joab, Abishai, and Asahel. Her name is always linked with her three sons. The sons she raised were exceedingly loyal and brave, yet also fierce and hard to tame—what a mother shapes should be both strength and character.",
 follow=["The courage and responsibility of raising the next generation"],
 caution=["Beyond strength, character that is restrained should also be shaped"],
 applications=["Cultivate both children's ability and character","Value a mother's far-reaching influence on the next generation","Pray that God add gentleness and self-control to your children's strength"],
 prayer="Lord, Zeruiah raised three fierce warriors. Help parents to cultivate both their children's strength and a character restrained by You. Amen."),
"希兰": dict(lesson="Advancing God's work with expertise and resources",
 summary="King of Tyre, who supplied materials for building the temple.",
 witness="Hiram was king of Tyre, friendly with David and Solomon, supplying cedar, craftsmen, and skill, advancing the building of the temple. Though a Gentile king, he took part in God's project with his resources and expertise—God also uses 'outside' blessings.",
 follow=["Advancing God's work with his own resources and expertise","Building mutual trust and cooperation with God's people"],
 caution=["Keeping God central in cooperation, not driven by gain"],
 applications=["Offer your profession and resources to take part in building God's kingdom","Build mutual trust and cooperation with people of different backgrounds","See that God can accomplish His work through 'outside' people"],
 prayer="Lord, Hiram king of Tyre advanced the temple building with his resources and expertise. Make me too willingly offer my skills, take part in Your work, and build Your house of one heart with all. Amen."),
"哈达": dict(lesson="An old grudge unresolved becomes a later enemy",
 summary="A descendant of Edom's royal house, an enemy in Solomon's later years.",
 witness="Hadad was a descendant of Edom's royal house who as a child fled to Egypt, escaping Joab's slaughter, harboring resentment all along. When Solomon strayed from God in his later years, God raised up Hadad as his enemy. An unresolved old grudge often returns when one is weak.",
 follow=[],
 caution=["Letting childhood trauma turn into lifelong resentment","Watching for a chance to take revenge, becoming a scourge in another's decline"],
 applications=["Deal with old grudges in your heart, lest they backfire when chance comes","Don't kick a man when he is down","Ask God to heal trauma and dissolve the root of hatred"],
 prayer="Lord, Hadad harbored an old grudge and became Solomon's enemy. Heal the trauma and bitterness in my heart, lest they take root in enmity, making me one who forgives rather than resents. Amen."),
"利逊": dict(lesson="Rising as an enemy when another strays",
 summary="An Aramean of Damascus, an enemy of Solomon.",
 witness="Rezon was an Aramean who gathered a band and occupied Damascus, becoming Israel's enemy in Solomon's later years when he strayed from God. God raised him up as an instrument of discipline. The rise of a strong enemy often accompanies God's people's spiritual straying.",
 follow=[],
 caution=["Rising as an enemy when another is weak and straying","Expanding himself by carving out territory and hostility"],
 applications=["Understand that spiritual straying invites the rise of 'enemies'","Keeping your relationship with God is keeping your safeguard","Don't attack and expand at another's peril"],
 prayer="Lord, when Solomon strayed, Rezon rose as an enemy. Make me keep my relationship with You, giving the enemy no opening, nor attacking people at their weakness. Amen."),
"尼八": dict(lesson="The son's evil crowned under the father's name",
 summary="Jeroboam's father.",
 witness="Nebat was Jeroboam's father. Scripture repeatedly says the northern kings did 'the evil of Jeroboam son of Nebat, who made Israel sin.' Nebat himself has little record, yet his name is repeatedly mentioned because of his son's great sin of setting up the golden calves. Children's influence also reflects back on the father's name.",
 follow=[],
 caution=["(A warning) children's evil deeds can bring shame on the family name"],
 applications=["Value spiritual guidance of children, lest it harm the family name","Pray for your children to walk the right path and not lead others into sin","Understand the family name is tied to descendants' conduct"],
 prayer="Lord, Nebat's name is repeatedly mentioned for his son's great sin. Help me guide the next generation in the right path, that the family name not be shamed by descendants' rebellion. Amen."),
"洗鲁阿": dict(lesson="A widow's son too can be raised up by God (or corrupted)",
 summary="Jeroboam's mother, a widow.",
 witness="Zeruah was Jeroboam's mother, a widow. Her son was raised up by God from being Solomon's servant and given the ten tribes of the north. Yet Jeroboam made all Israel sin with golden calves. A child raised by the same mother can be exalted by God or go to corruption—the key lies in his own choice.",
 follow=["(A reminder to mothers) raising children amid hardship (widowhood)"],
 caution=["(Background) the son, after being exalted, led in sin—lamentable"],
 applications=["Wholeheartedly raise the next generation even in hard situations (such as single parenting)","Pray for those exalted by God, lest they fall after being exalted","Understand that after being shown grace one must guard oneself all the more, not waste it"],
 prayer="Lord, Zeruah's son was exalted yet led in sin. Help me raise the next generation amid hardship, and keep those shown grace and exalted from falling, guarding themselves to the end. Amen."),
"示撒": dict(lesson="Forsaking God, the safeguard is lost with it",
 summary="King of Egypt who attacked Jerusalem and seized the temple treasures.",
 witness="Shishak was king of Egypt who, in the fifth year after Rehoboam forsook the LORD's law, marched up to attack Jerusalem, taking the gold treasures of the temple and palace, even the gold shields Solomon made, which had to be replaced with bronze. Forsake God, and yesterday's glory and safeguard drain away one after another.",
 follow=[],
 caution=["Invading and plundering when another forsakes God and loses protection","Plundering God's temple and holy things, with no regard for God"],
 applications=["Understand that when you forsake God, the spiritual safeguard is lost with it","Keeping your relationship with God is keeping the true safeguard","Don't plunder at another's peril"],
 prayer="Lord, when Rehoboam forsook You, Shishak came to plunder. Make me hold tightly to my relationship with You, not letting yesterday's grace drain away through my straying. Amen."),
"所罗门的外邦妃嫔": dict(lesson="The influence at one's side can turn a wise heart aside",
 summary="The foreign women who turned Solomon's heart from the LORD.",
 witness="Solomon married many foreign wives and concubines, who each brought in their nations' idols. When Solomon was old, 'his wives turned away his heart after other gods,' and the wisest of kings even built high places for them. The subtle influence of the closest people can turn a heart toward God aside, little by little.",
 follow=[],
 caution=["Bringing in influence that strays from God in the closest relationship","Drawing people after other gods through emotional subtlety"],
 applications=["Be careful of the closest relationship's influence on your faith's direction","In intimate relationships be the one who draws people to God, not away","Keep singleness toward God, not turned aside by pillow talk"],
 prayer="Lord, the foreign wives turned Solomon's heart from You. Keep me single toward You even in the closest relationships, and make me an influence drawing people to You, not away. Amen."),
"西缅（雅各之子）": dict(lesson="The fierce anger of the flesh needs to be managed by God",
 summary="The second son of Jacob and Leah, ancestor of the tribe of Simeon, who avenged Dinah on Shechem.",
 witness="Simeon was the second son of Jacob and Leah, who for his sister Dinah's defilement, with Levi by a ruse slaughtered the whole city of Shechem. He had a fierce love to protect kin, but with cruelty crossed the line of justice, and at the end his father prophesied his descendants would be scattered in Israel. Fierce anger unmanaged by God becomes a curse.",
 follow=["Having real pain and responsibility over family being violated"],
 caution=["Crossing the line of justice with the fierce anger of the flesh","Handling wrongs by ruse and excessive revenge"],
 applications=["When righteous indignation comes, give it to God, not letting the flesh run","Handle offenses by justice rather than private vengeance","Ask God to manage your fierceness, making it a blessing not a destruction"],
 prayer="Lord, Simeon's fierce anger crossed into cruelty. Manage the flesh and anger in me, that I face wrongs with justice and patience, not letting fierceness harm others and myself. Amen."),
"利未（雅各之子）": dict(lesson="The scattered, God can also set apart as holy",
 summary="The third son of Jacob and Leah, ancestor of the tribe of Levi and the priesthood.",
 witness="Levi was Jacob's third son, who with Simeon once slaughtered a city out of fleshly anger, and was prophesied to be scattered in Israel. Yet at the exodus, the tribe of Levi, by standing on the LORD's side, had this scattering transformed by God into the office of priests and teachers distributed throughout the land—the curse turned by grace into service.",
 follow=["Standing on God's side at the crucial moment","Letting God transform past failure into a calling to serve"],
 caution=["Youthful fleshly anger once brought a curse; take warning"],
 applications=["Give the 'scattering' and failures of life to God, asking Him to transform them into blessing","Stand firmly on God's side at moments of decision","Value the calling to teach and serve"],
 prayer="Lord, You turned Levi's scattering into holy service set apart. Turn my failures and brokenness too, by Your grace, into a vessel serving You and blessing people. Amen."),
"巴沙": dict(lesson="Rising by slaughter, yet walking the predecessors' old road",
 summary="A wicked northern king who usurped Nadab's throne.",
 witness="Baasha usurped Nadab's throne and wiped out Jeroboam's whole house, fulfilling prophecy, yet himself likewise did Jeroboam's evil, making Israel sin. He was used by God to execute judgment, yet did not learn from the fate of the judged, and finally his own house met the same curse.",
 follow=[],
 caution=["Seizing power by slaughter and coup","Used by God to judge others, yet not taking warning himself","Repeating the predecessors' road of plunging the nation into sin"],
 applications=["Don't seize position by unjust means","Learn from others' failures, rather than repeat them","After gaining power, do what is right in God's eyes"],
 prayer="Lord, Baasha wiped out a wicked king, yet walked the same old road. Make me take warning from others' falls, not repeat them, doing what is right in Your eyes. Amen."),
"以拉（以色列王）": dict(lesson="Drowning in revelry, disaster at the door unaware",
 summary="Baasha's son, a northern king, killed by Zimri while drunk.",
 witness="Elah was Baasha's son, king of Israel. While the army was fighting at the front, he was getting drunk in the house of his steward, and was assassinated by his subordinate Zimri, and Baasha's whole house was destroyed with him. In high office yet indulging in pleasure and neglecting duty, he was utterly unaware when disaster came.",
 follow=[],
 caution=["Indulging pleasure and neglecting duty when he should be doing his job","Numbing himself with drunkenness, losing vigilance"],
 applications=["Don't indulge enjoyment when responsibility is at hand","Stay sober and vigilant, not numbed by pleasure","Value the office entrusted, not neglecting duty"],
 prayer="Lord, Elah got drunk and bungled, unaware when disaster came. Make me sober and vigilant in the responsibility entrusted, not indulging pleasure, a faithful and watchful person. Amen."),
"心利": dict(lesson="Seven days of kingship, exchanged for an everlasting infamy",
 summary="A usurper who reigned only seven days.",
 witness="Zimri was Elah's subordinate who, while the king was drunk, killed his lord and usurped the throne, but reigned only seven days. When Omri led the army to besiege the city and Zimri saw all was lost, he set the palace on fire and died in the flames. A position grabbed by betrayal came to nothing in a flash, leaving only the infamy of 'king-killer.'",
 follow=[],
 caution=["Seizing power by betrayal and regicide","A grabbed position is shallow-rooted and fleeting"],
 applications=["Don't seize what you want by betrayal and injustice","Remember what is gained unjustly often comes to nothing in a flash","Between loyalty and shortcuts, choose loyalty"],
 prayer="Lord, Zimri seized the throne by regicide and perished in seven days. Keep me from the shortcuts of betrayal and deceit, acting with loyalty and integrity, not coveting a momentary gain. Amen."),
"提比尼": dict(lesson="Losing a power contest also warns of strife's cost",
 summary="Who failed in the contest for the throne with Omri.",
 witness="When Omri gained the kingdom, the people of Israel were divided in two: half followed Tibni, half Omri. The two factions contended; Tibni lost and died, and Omri prevailed. A contest for the throne further divided and drained the already weak northern kingdom.",
 follow=[],
 caution=["Getting drawn into factional struggle for power","Further dividing the community in internal drain"],
 applications=["Don't lightly get drawn into factional and power struggles","Seek unity amid differences, reducing internal drain","Put energy into building rather than vying for position"],
 prayer="Lord, Tibni lost in the contest for the throne, and the north was more divided. Make me not get drawn into pointless factional strife, but be one who promotes unity and builds the community. Amen."),
"撒迦利雅（以色列王）": dict(lesson="The end of a dynasty, fulfilling God's word",
 summary="The last of Jehu's dynasty, who reigned six months and was killed.",
 witness="Zechariah was the great-great-grandson of Jehu, the last king of Jehu's dynasty, who reigned only six months before Shallum killed him publicly, fulfilling God's word to Jehu that 'your sons to the fourth generation shall sit on Israel's throne.' God's promise and limit were fulfilled to the letter.",
 follow=[],
 caution=["Inheriting the dynasty yet continuing the tradition of doing evil","The dynasty's blessing used up, judgment following"],
 applications=["Don't rely on the family's past blessing; do righteousness yourself","Remember God's word will surely be fulfilled, not to be taken lightly","Treasure and continue, rather than exhaust, your spiritual inheritance"],
 prayer="Lord, Zechariah was the last of Jehu's dynasty, fulfilling Your word. Make me not rely on past blessing, but do righteousness with a fearing heart to the end. Amen."),
"沙龙（以色列王）": dict(lesson="Usurping for one month, confirming the judgment",
 summary="Who killed Zechariah and usurped the throne, reigning only one month.",
 witness="Shallum killed Zechariah and usurped the throne, ending Jehu's dynasty, but reigned only one month before Menahem killed him. The regicides in the north's late period came like a lantern's spinning figures; Shallum was but one link—betrayal brought betrayal, bloodshed invited bloodshed.",
 follow=[],
 caution=["Beginning with regicide and usurpation, ending in being killed","Caught in the cycle of revenge-for-revenge violence"],
 applications=["Refuse to solve power problems with violence and betrayal","Don't take part in the cycle of revenge for revenge","Ask God to keep your integrity amid turmoil"],
 prayer="Lord, Shallum usurped by regicide and was killed in a flash. Keep me from the cycle of violence and betrayal, facing power and conflict with integrity and reverence. Amen."),
"米拿现": dict(lesson="Brutal yet seeking false security, leaving a heavy cost",
 summary="A brutal northern king who paid tribute to Assyria.",
 witness="Menahem was a northern king who consolidated power with extremely brutal means, and paid heavy silver to the king of Assyria for support, shifting the burden onto the people. He bought momentary security with outside force, but laid the groundwork for the north's destruction. Brutality plus expediency—the cost borne by later generations.",
 follow=[],
 caution=["Consolidating power by brutal means","Bribing a strong enemy for false security, sacrificing the people"],
 applications=["Don't consolidate your position by harming others","Don't sacrifice the long-term and others' interests for momentary security","Consider the people's burden when holding power"],
 prayer="Lord, Menahem was brutal and sought false security, harming later generations. Make me not protect myself by harming people, nor sacrifice others for security, but be one who cares for people and fears You. Amen."),
"比加辖": dict(lesson="An inherited throne cannot stop internal betrayal",
 summary="Menahem's son, killed by Pekah.",
 witness="Pekahiah succeeded his father Menahem as king of Israel, did evil in the LORD's eyes, and after only two years on the throne was killed by his own commander Pekah. An inherited position, without reverence and foundation, is seized in a flash by those at one's side.",
 follow=[],
 caution=["Inheriting the position yet inheriting the same evil","Lax in guarding against ambition at his side amid turmoil"],
 applications=["Don't only inherit position, but inherit integrity and reverence","Do what is right in God's eyes while in office","Stay clear-eyed about ambition around you"],
 prayer="Lord, Pekahiah inherited the throne yet did evil and was killed. Make me inherit not only the office but reverence and integrity, doing what is right in Your eyes in my place. Amen."),
"比加": dict(lesson="Regicide and alliance accelerate a nation's collapse",
 summary="A northern king who allied with Rezin to attack Judah, and lost territory to Assyria.",
 witness="Pekah usurped the throne by killing Pekahiah, then allied with Rezin king of Aram to attack Judah, inviting Assyria's retaliation, with large swaths of the north's land and people taken captive. He sought to strengthen himself by force and alliance, but instead accelerated the nation's collapse, and was finally killed by Hoshea.",
 follow=[],
 caution=["Seeking strength by regicide and military adventure","A wrong alliance setting himself on fire"],
 applications=["Don't solve a predicament by violence and a risky alliance","Carefully judge the consequences of an alliance","In crisis seek God, not a bigger gamble"],
 prayer="Lord, Pekah sought strength by regicide and alliance, and instead accelerated his ruin. Give me, in crisis, not to gamble all or rely on a wrong alliance, but seek Your guidance alone. Amen."),
"耶户（哈拿尼之子）": dict(lesson="Both to rebuke and to affirm",
 summary="The prophet who rebuked Jehoshaphat's alliance with Ahab.",
 witness="Jehu was the son of the seer Hanani, who both rebuked Jehoshaphat for allying with the wicked king Ahab, and affirmed his good of 'removing the Asherah poles and setting his heart to seek God.' His rebuke had measure and fairness—pointing out the wrong, yet also seeing the good.",
 follow=["When correcting others, both saying the needed rebuke and affirming the good","Treating people with fairness, not blanket negation"],
 caution=["Not erasing another's merits just because you must rebuke"],
 applications=["When correcting people, first affirm what is commendable, then point out the problem","Keep fairness and measure in evaluation","Pray for those in power, and dare to remind them"],
 prayer="Lord, Jehu rebuked Jehoshaphat and also affirmed his good. Make me correct people with measure and fairness, both speaking truth and seeing and affirming others' good. Amen."),
"亚撒利雅（俄德之子）": dict(lesson="A timely exhortation ignites reform",
 summary="The prophet who exhorted Asa to carry out religious reform.",
 witness="Azariah was the son of Oded, who went out to meet Asa returning victorious and said: if you seek God, He will be found; if you forsake Him, He will forsake you. One timely exhortation strengthened Asa's heart and drove a revival of removing idols and repairing the altar.",
 follow=["Giving people timely spiritual exhortation at the crucial moment","Turning people's hearts to seek God"],
 caution=["Exhortation must be grounded in God's word, not empty talk"],
 applications=["Give timely spiritual encouragement to others in victory or in a low point","Strengthen people's faith with God's promises","Be a voice driving revival and turning back"],
 prayer="Lord, Azariah's one timely word ignited reform. Make me a mouth that exhorts people in time, turning hearts to seek You, driving turning-back and revival. Amen."),
"撒迦利亚（耶何耶大之子）": dict(lesson="Faithful unto death, the blood not shed in vain",
 summary="The priest stoned to death for rebuking Joash.",
 witness="Zechariah was the son of the high priest Jehoiada. Joash forgot his father's kindness, and when Zechariah rebuked the people by God's command, he ordered him stoned to death in the temple court. As he died he said: may the LORD see and avenge. Faithful martyrdom, God remembers and will require.",
 follow=["Faithfully preaching God's word, unchanging unto death","Leaving vengeance to the God who sees all things"],
 caution=["(A warning to Joash) ingratitude, repaying kindness with enmity"],
 applications=["Be faithful to God's charge, not shrinking even in danger","When wronged, entrust vengeance to God","Don't be ungrateful or repay with enmity those who helped you"],
 prayer="Lord, Zechariah faithfully spoke Your word unto death, and You will avenge him. Make me faithful to the end, leaving vengeance to You when wronged, and be one who is not ungrateful. Amen."),
"乌利亚祭司": dict(lesson="Flattering the ruler distorted the holy altar",
 summary="The priest who built an altar for Ahaz after the pattern of Damascus.",
 witness="Uriah was a priest in Ahaz's time. The king saw a pagan altar pattern in Damascus and ordered one built like it, and Uriah did exactly so, moving the LORD's bronze altar aside. He traded obedience for the king's favor, but altered God's holy altar beyond recognition.",
 follow=[],
 caution=["Compromising the principles of faith to please the ruler","Bringing worldly patterns into sacred worship"],
 applications=["Don't compromise truth and principle to please superiors","Guard the purity of worship, not drifting with the crowd","Discern under pressure: obey people or obey God"],
 prayer="Lord, Uriah remade Your altar to please Ahaz. Make me not compromise Your truth to please people, guarding the purity of worship, obeying You over people. Amen."),
"希勒家": dict(lesson="A scroll of law brought back to light, bringing national revival",
 summary="The high priest in Josiah's time, who found the Book of the Law.",
 witness="Hilkiah was the high priest in Josiah's time, who found the long-lost Book of the Law while repairing the temple. He did not suppress this astonishing discovery, but reported it at once, sparking Josiah's deep repentance and a great revival cleansing the whole land. Faithfully guarding and conveying God's word can change an age.",
 follow=["Treasuring and conveying God's word, not hiding it","Faithful in his post, bringing out a greater influence"],
 caution=["Don't let God's word gather dust in the 'storehouse'"],
 applications=["Pick up again the word of God you have neglected","Pass on the truth you've received, not hoarding it","Trust God's word can bring real renewal"],
 prayer="Lord, Hilkiah found the Book of the Law and brought national revival. Make me treasure and convey Your word, not let it gather dust, but let it bring renewal in me and those around me. Amen."),
"沙番": dict(lesson="Faithfully reporting, a bridge between king and God",
 summary="The scribe in Josiah's time who read the Book of the Law.",
 witness="Shaphan was Josiah's scribe, who read the Book of the Law Hilkiah found to the king word for word, and faithfully managed the temple repair affairs. He was not a prophet, yet with the faithfulness of an official he delivered God's word accurately to the king, bringing about reform.",
 follow=["Faithful and accurate in his own post","Being a bridge connecting truth and the decision-maker"],
 caution=["Not editing or glossing the message he was to convey"],
 applications=["Be faithful and dutiful in clerical, administrative, and like posts","Convey information accurately, not smuggling in your own bias","Value the impact of an 'inconspicuous' duty on the big picture"],
 prayer="Lord, Shaphan faithfully read Your word to the king and brought about reform. Make me faithful and accurate in my post, a bridge connecting truth and people's hearts. Amen."),
"亚希甘": dict(lesson="One who guards the truth with his own influence",
 summary="Shaphan's son, who protected Jeremiah.",
 witness="Ahikam was the son of the scribe Shaphan, an important official under Josiah. When Jeremiah faced death threats for conveying God's word, it was Ahikam who stepped in to protect him, so he was not handed over to the people to be killed. He used his position and influence to guard a prophet who spoke truth but was unwelcome.",
 follow=["Using his position and influence to protect those who speak truth","Stepping in to guard the righteous amid public fury"],
 caution=["Not suppressing the unwelcome teller of truth along with the crowd"],
 applications=["Use your influence to protect those who speak truth and do justice","Be the voice that guards the righteous amid public fury","Don't go along with suppressing truth just because it is jarring"],
 prayer="Lord, Ahikam used his position to guard Jeremiah. Make me use all my influence to protect those who speak truth and do justice, stepping in to guard truth amid public fury. Amen."),
"约拿达（利甲之子）": dict(lesson="Setting a tradition that shaped generations of obedience",
 summary="The founder of the Rechabites' tradition of not drinking wine.",
 witness="Jonadab was the founder of the Rechabites' tradition of not drinking wine, not building houses, and living in tents. Centuries later, his descendants the Rechabites still faithfully kept their ancestor's command, set up by God as a model of obedience, in contrast to rebellious Judah. A godly family rule can shape generations of loyalty.",
 follow=["Setting and passing on a godly, self-disciplined family rule","Setting blessed spiritual boundaries for descendants"],
 caution=["Tradition must be under God's will, not rigid"],
 applications=["Set good, godly, self-disciplined traditions for your family","Lead by example, so descendants gladly keep them","Value a family rule's long-term shaping of generations"],
 prayer="Lord, Jonadab's family rule shaped generations of Rechabite obedience. Help me set godly traditions for my family, leading by example, shaping descendants' loyalty. Amen."),
}
